import dataUrl from './airspace-data.json?url';
import type { TfrInfo } from './tfr';

// Airspace volumes: the data model behind the 3D airspace layer
// (world/airspace.ts) and the detail card's "Airspace" row.
//
// airspace-data.json is generated by scripts/build-airspace.py from the
// FAA's open data (US only; do not hand-edit): Class B, C and D plus
// special use airspace, each a ground outline with a floor and a ceiling.
// It is fetched once, on first use, as a hashed static asset; nothing is
// requested until a user turns the layer on, and the running container
// never contacts the FAA.
//
// Everything above the loader is pure so it can be unit tested without a
// scene: decoding, the nearby filter and point-in-volume.

export type AirspaceKind = 'B' | 'C' | 'D' | 'MOA' | 'R' | 'P' | 'W' | 'A' | 'TFR';

/** Controlled airspace around airports. */
export const CONTROLLED_KINDS: readonly AirspaceKind[] = ['B', 'C', 'D'];
/** Special use airspace: MOA, restricted, prohibited, warning, alert. */
export const SPECIAL_KINDS: readonly AirspaceKind[] = ['MOA', 'R', 'P', 'W', 'A'];
/** Every kind the layer can draw; 'TFR' is live (world/tfr.ts), the rest come from the generated file. */
export const ALL_KINDS: readonly AirspaceKind[] = [...CONTROLLED_KINDS, ...SPECIAL_KINDS, 'TFR'];

export interface AirspaceVolume {
  name: string;
  kind: AirspaceKind;
  /** Shelf of a larger airspace ("AREA C"), when the FAA names one. */
  sector: string | null;
  /** Floor and ceiling in feet, MSL unless the matching Agl flag is set. */
  loFt: number;
  hiFt: number;
  loAgl: boolean;
  hiAgl: boolean;
  /** Published ceiling is "unlimited"; hiFt is a drawing cap. */
  unlimited: boolean;
  /** Times of use as published (special use airspace only). */
  times: string | null;
  /** [polygon][ring][lon, lat, ...]; ring 0 is the outline, the rest holes. */
  polygons: readonly (readonly (readonly number[])[])[];
  /** [west, south, east, north]. */
  bbox: readonly [number, number, number, number];
  /** The NOTAM behind a temporary flight restriction (kind 'TFR' only). */
  tfr?: TfrInfo;
}

interface RawVolume {
  n: string;
  k: string;
  lo: number;
  hi: number;
  la?: number;
  ha?: number;
  u?: number;
  s?: string;
  t?: string;
  g: number[][][];
}

const KINDS = new Set<string>([...CONTROLLED_KINDS, ...SPECIAL_KINDS]);
const NM_PER_DEG = 60;

/** Parse the generated file; rows that do not fit the schema are dropped. */
export function decodeVolumes(raw: unknown): AirspaceVolume[] {
  const rows = (raw as { volumes?: RawVolume[] } | null)?.volumes;
  if (!Array.isArray(rows)) return [];
  const out: AirspaceVolume[] = [];
  for (const r of rows) {
    if (!r || !KINDS.has(r.k) || !Array.isArray(r.g) || !Number.isFinite(r.lo) || !Number.isFinite(r.hi)) continue;
    let west = Infinity;
    let south = Infinity;
    let east = -Infinity;
    let north = -Infinity;
    for (const poly of r.g) {
      const outline = poly[0];
      if (!outline) continue;
      for (let i = 0; i + 1 < outline.length; i += 2) {
        const lon = outline[i]!;
        const lat = outline[i + 1]!;
        if (lon < west) west = lon;
        if (lon > east) east = lon;
        if (lat < south) south = lat;
        if (lat > north) north = lat;
      }
    }
    if (!Number.isFinite(west)) continue;
    out.push({
      name: r.n,
      kind: r.k as AirspaceKind,
      sector: r.s ?? null,
      loFt: r.lo,
      hiFt: r.hi,
      loAgl: r.la === 1,
      hiAgl: r.ha === 1,
      unlimited: r.u === 1,
      times: r.t ?? null,
      polygons: r.g,
      bbox: [west, south, east, north],
    });
  }
  return out;
}

/** Distance in NM from a point to a volume's bounding box (0 inside it). */
export function distanceToVolumeNm(v: Pick<AirspaceVolume, 'bbox'>, lat: number, lon: number): number {
  const [west, south, east, north] = v.bbox;
  const dLat = lat < south ? south - lat : lat > north ? lat - north : 0;
  const dLon = lon < west ? west - lon : lon > east ? lon - east : 0;
  const cos = Math.cos((lat * Math.PI) / 180);
  return Math.hypot(dLat * NM_PER_DEG, dLon * NM_PER_DEG * cos);
}

/** Volumes of the given kinds whose bounding box comes within radiusNm. */
export function volumesNear(
  volumes: readonly AirspaceVolume[],
  lat: number,
  lon: number,
  radiusNm: number,
  kinds: ReadonlySet<AirspaceKind>,
): AirspaceVolume[] {
  return volumes.filter((v) => kinds.has(v.kind) && distanceToVolumeNm(v, lat, lon) <= radiusNm);
}

/** Even-odd test against one flat [lon, lat, ...] ring. */
export function pointInRing(ring: readonly number[], lon: number, lat: number): boolean {
  let inside = false;
  const n = ring.length / 2;
  for (let i = 0, j = n - 1; i < n; j = i++) {
    const xi = ring[i * 2]!;
    const yi = ring[i * 2 + 1]!;
    const xj = ring[j * 2]!;
    const yj = ring[j * 2 + 1]!;
    if (yi > lat !== yj > lat && lon < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

/** Is (lat, lon) over the volume's footprint (inside an outline, outside its holes)? */
export function overVolume(v: AirspaceVolume, lat: number, lon: number): boolean {
  const [west, south, east, north] = v.bbox;
  if (lon < west || lon > east || lat < south || lat > north) return false;
  for (const poly of v.polygons) {
    if (!poly[0] || !pointInRing(poly[0], lon, lat)) continue;
    let inHole = false;
    for (let h = 1; h < poly.length; h++) {
      if (pointInRing(poly[h]!, lon, lat)) {
        inHole = true;
        break;
      }
    }
    if (!inHole) return true;
  }
  return false;
}

/** Floor and ceiling in feet MSL given the ground elevation under the volume. */
export function limitsMsl(v: AirspaceVolume, groundFt: number): { lo: number; hi: number } {
  return {
    lo: v.loAgl ? groundFt + v.loFt : v.loFt,
    hi: v.hiAgl ? groundFt + v.hiFt : v.hiFt,
  };
}

/**
 * Volumes containing the point. The ceiling is inclusive, as published
 * ("to and including 10,000"); an aircraft on the ground is inside any
 * volume that starts at the surface.
 */
export function volumesAt(
  volumes: readonly AirspaceVolume[],
  lat: number,
  lon: number,
  altFt: number,
  groundFt: number,
  onGround = false,
): AirspaceVolume[] {
  const out: AirspaceVolume[] = [];
  for (const v of volumes) {
    if (!overVolume(v, lat, lon)) continue;
    const { lo, hi } = limitsMsl(v, groundFt);
    const surface = v.loAgl && v.loFt === 0;
    if (onGround ? surface : (surface || altFt >= lo) && altFt <= hi) out.push(v);
  }
  return out;
}

const KEEP_UPPER = new Set(['TFR', 'VIP', 'UAS', 'MOA', 'ATCAA', 'AFB', 'NAS', 'AAF', 'ANGB', 'MCAS', 'NOLF', 'II', 'III', 'IV']);

/** "MINNEAPOLIS CLASS B" -> "Minneapolis Class B"; designators like "R-6904A" stay as published. */
export function airspaceTitle(name: string): string {
  return name
    .split(/\s+/)
    .filter(Boolean)
    .map((word) => {
      if (/\d/.test(word) || KEEP_UPPER.has(word)) return word;
      return word
        .split('-')
        .map((part) => (part ? part[0]!.toUpperCase() + part.slice(1).toLowerCase() : part))
        .join('-');
    })
    .join(' ');
}

// ── Loader ──────────────────────────────────────────────────────────
// Subscribe-pattern singleton: one fetch, shared by the layer and the
// detail card. A failed fetch leaves the layer empty and is retried on
// the next request.

let volumes: AirspaceVolume[] | null = null;
let loading: Promise<void> | null = null;
const listeners = new Set<() => void>();

/** Loaded volumes, or null until loadAirspace() has finished. */
export function getAirspace(): readonly AirspaceVolume[] | null {
  return volumes;
}

export function subscribeAirspace(fn: () => void): () => void {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

export function loadAirspace(): Promise<void> {
  if (volumes) return Promise.resolve();
  loading ??= fetch(dataUrl)
    .then((res) => {
      if (!res.ok) throw new Error(`airspace data: HTTP ${res.status}`);
      return res.json() as Promise<unknown>;
    })
    .then((raw) => {
      volumes = decodeVolumes(raw);
      for (const fn of listeners) fn();
    })
    .catch((err: unknown) => {
      console.warn('[airspace] could not load volumes', err);
      loading = null;
    });
  return loading;
}
